import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        long m = Long.parseLong(next());
        String[] a = new String[(int) n];
        for (int i = 0; i < a.length; i++) a[i] = next();
        String[] b = new String[(int) m];
        for (int i = 0; i < b.length; i++) b[i] = next();

        Map<String, Integer> pos = new HashMap<>();
        for (int i = 0; i < n; i++) pos.put(a[i], i);
        int best = -1;
        List<String> result = new ArrayList<>();
        for (int j = 0; j < m; j++) {
            Integer i = pos.get(b[j]);
            if (i == null) continue;
            int s = i + j;
            if (best == -1 || s < best) {
                best = s;
                result.clear();
                result.add(b[j]);
            } else if (s == best) {
                result.add(b[j]);
            }
        }
        Collections.sort(result);
        System.out.println(result.size());
        System.out.println(String.join(" ", result));
    }
}
